sys_script.script:
(function executeRule(current, previous /*null when async*/) {
   gs.info('Number Range '+current.u_year + current.applicant_name.company.name + current.main_expense + current.sub_expense + current.u_project_type);
	if(current.u_year && current.applicant_name.company.name && current.main_expense && current.sub_expense && current.u_project_type){
       current.u_number_range = current.u_project_type.slice(-1)+"/"+current.applicant_name.company.name.slice(-2)+current.u_year.slice(-2)+"."+current.main_expense+"."+current.sub_expense;
	}
	else if(current.u_year && current.applicant_name.company.name && current.product_category && current.activity && current.campaign){
		current.u_number_range = current.u_project_type.slice(-1)+"/"+current.applicant_name.company.name.slice(-2)+current.u_year.slice(-2)+"."+current.product_category+"."+current.activity+"."+current.campaign;
	}
	else if(current.u_year && current.applicant_name.company.name && current.product_category && current.sub_expense && current.advertising_type){
      current.u_number_range = current.u_project_type.slice(-1)+"/"+current.applicant_name.company.name.slice(-2)+current.u_year.slice(-2)+"."+current.product_category+"."+current.advertising_type+"."+current.sub_expense;
	}

    else if(current.u_year && current.applicant_name.company.name && current.department && current.sub_expense && current.main_expense){
      current.u_number_range = current.u_project_type.slice(-1)+"/"+current.applicant_name.company.name.slice(-2)+current.u_year.slice(-2)+"."+current.department+"."+current.main_expense+"."+current.sub_expense;
	}
    else if(current.u_year && current.applicant_name.company.name && current.sub_expense && current.main_expense){
      current.u_number_range = current.u_project_type.slice(-1)+"/"+current.applicant_name.company.name.slice(-2)+current.u_year.slice(-2)+"."+current.main_expense+"."+current.sub_expense;
	}
	else if(current.u_year && current.applicant_name.company.name&& current.activity_type  && current.channel && current.sub_expense){
      current.u_number_range = current.u_project_type.slice(-1)+"/"+current.applicant_name.company.name.slice(-2)+current.u_year.slice(-2)+"."+current.activity_type+"."+current.channel+"."+current.sub_expense;
	}
})(current, previous);
